// gl_func_000250C8 — RECONSTRUCTED DECODE (67.15 -> 85.15% fuzzy, no episode).
// Object-tick / advance-state entry of the game_libs object subsystem.
// Reconstructed from the linked-ELF disassembly (agent-b). All mid-function
// jal targets (0x37dcc/0x39b70/0x39a1c/0x3998c) plus the USO-relocated leaf
// calls are represented by the canonical never-defined placeholder
// gl_func_00000000 (same convention as sibling gl_func_00023838) — those
// baked-jal words are the inherent USO-reloc residual, so this can NEVER be
// byte-exact / landed until USO-reloc infra exists. Globals: D+0x2024 =
// shared registry ptr (`reg`, read as *(short*)(reg+2) in the count path);
// D+0x2030 = registry table base (0x14 stride). Logic landed via: signed-byte
// mode read; switch(kind) on (field18>>16)&0xff (case 0/1/2 ordering); buf[6]
// stack-struct packing for the c2/c3/result/out-param sextet passed to 39b70;
// scalar c2/c3 (kept register-resident -> beq not beql); sub-reused-as-idx
// to coalesce the spill slot (frame -96). RESIDUAL CAPS (matches sibling's
// 85% plateau): (1) IDO -O2 cross-jumps the identical case 0 / case 2 bodies
// that the target keeps separate; (2) lower-half (count/sub) $a2-vs-temp
// register-coloring tie; (3) one bne operand-order diff. Genuine
// regalloc-coloring + cross-jump residual — NM-wrap.
// Run 129 (agent-c) 82 -> 61 raw: the target lays the switch out as
// case 0, case 2, case 1 (source order 0, 2, 1 -- the "cross-jump" was just
// order); sub/rem unsigned (sltu); decl order puts sub lowest; the compare
// reads obj->14 directly and rem is loaded for the second branch. LEFT: frame
// 104 vs 96 (two extra slots), rem homed at 48 instead of coloured a2, the
// 3998c call takes sub reloaded into a2 (target a1 reload, a2 = t2).
// Run 143 (agent-c) 92.31 -> 97.62: OoT AudioLoad_ProcessAsyncLoad with
// FinishAsyncLoad inline. The target spills bytesRemaining and fontId to ONE
// slot (sp+36) because both are compiler temps in the temp area below the
// locals, not declared variables: re-reading asyncLoad->bytesRemaining at each
// use (no cached local) moves it from its home (+84) to +36. LEFT: case-1
// fontId still homed at +84, the retMsg web coloured v0 (target a1 + v0 copy).
// Run 278 (agent-g) 99.85 -> EXACT: the OoT FinishAsyncLoad body as written --
// every case reads the retMsg local, fontId = ASYNC_ID(retMsg) (copy-propagated:
// its value is a uopt temp spilled to the bytesRemaining word +36, not a home),
// and the done message sent straight from asyncLoad->retMsg -- once the callees
// take the message / font id as u32 (no u32 -> s32 / u32 -> void * conversion on
// the argument): the osSendMesg message is OSMesg = a 32-bit word; with the
// void * parameter the cast kept the reload in a separate web (a3 + copy to a1),
// with u32 the reload loads straight into a1 and the retMsg web splits a1 / v0
// like the target. The run-144 / run-149 levers are no longer needed.
typedef struct { void *a; void *b; s32 validCount; s32 first; s32 msgCount; void *msg; } gl_250C8_OSMesgQueue;
typedef struct {
    s8 status; s8 delay; s8 medium; u8 *ramAddr; u32 curDevAddr; u8 *curRamAddr; u32 bytesRemaining; u32 chunkSize;
    u32 retMsg; gl_250C8_OSMesgQueue *retQueue; gl_250C8_OSMesgQueue msgQueue;
} gl_250C8_AudioAsyncLoad;
typedef struct { s32 sampleBankId1; s32 sampleBankId2; s32 baseAddr1; s32 baseAddr2; u32 medium1; u32 medium2; } gl_250C8_SampleBankRelocInfo;
typedef struct { u8 numInstruments; u8 numDrums; u8 sampleBankId1; u8 sampleBankId2; char pad4[0x10]; } gl_250C8_SoundFont;
typedef struct { s16 numEntries; s16 unkMediumParam; } gl_250C8_AudioTable;
typedef struct { char pad0[0x2024]; gl_250C8_AudioTable *sampleBankTable; char pad2028[8]; gl_250C8_SoundFont *soundFontList; } gl_250C8_Ctx;
extern gl_250C8_Ctx gl_250C8_gAudioCtx;
#define gAudioCtx gl_250C8_gAudioCtx
extern s32 gl_250C8_osRecvMesg(void *, void *, s32);
extern s32 gl_250C8_osSendMesg(void *, u32, s32);
extern void gl_250C8_SetSeqLoadStatus(s32, s32);
extern void gl_250C8_SetSampleFontLoadStatus(s32, s32);
extern void gl_250C8_SetFontLoadStatus(u32, s32);
extern s32 gl_ref_00037DCC(s32, u32 *);
extern s32 gl_ref_00039B70(u32, void *, gl_250C8_SampleBankRelocInfo *, s32);
extern void gl_ref_00039A1C(u32, void *, u32, s32);
extern void gl_ref_0003998C(gl_250C8_AudioAsyncLoad *, u32);
#define AudioLoad_GetSampleBank gl_ref_00037DCC
#define AudioLoad_RelocateFontAndPreloadSamples gl_ref_00039B70
#define AudioLoad_AsyncDmaUnkMedium gl_ref_00039A1C
#define AudioLoad_AsyncDma gl_ref_0003998C
#define ASYNC_TBLTYPE(x) (((x) >> 16) & 0xFF)
#define ASYNC_ID(x) (((x) >> 8) & 0xFF)
#define ASYNC_STATUS(x) ((x) & 0xFF)

void gl_func_000250C8(gl_250C8_AudioAsyncLoad *asyncLoad, s32 resetStatus) {
    gl_250C8_AudioTable *sampleBankTable = gAudioCtx.sampleBankTable;
    u32 retMsg;
    u32 fontId;
    u32 pad;
    void *doneMsg;
    u32 sampleBankId1;
    u32 sampleBankId2;
    gl_250C8_SampleBankRelocInfo sampleBankReloc;

    if (asyncLoad->delay >= 2) {
        asyncLoad->delay--;
        return;
    }

    if (asyncLoad->delay == 1) {
        asyncLoad->delay = 0;
    } else if (resetStatus != 0) {
        gl_250C8_osRecvMesg(&asyncLoad->msgQueue, NULL, 1);
        asyncLoad->status = 0;
        return;
    } else if (gl_250C8_osRecvMesg(&asyncLoad->msgQueue, NULL, 0) == -1) {
        return;
    }

    if (asyncLoad->bytesRemaining == 0) {
        retMsg = asyncLoad->retMsg;
        switch ((s32)ASYNC_TBLTYPE(retMsg)) {
            case 0:
                gl_250C8_SetSeqLoadStatus(ASYNC_ID(retMsg), ASYNC_STATUS(retMsg));
                break;

            case 2:
                gl_250C8_SetSampleFontLoadStatus(ASYNC_ID(retMsg), ASYNC_STATUS(retMsg));
                break;

            case 1:
                fontId = ASYNC_ID(retMsg);
                gl_250C8_SetFontLoadStatus(fontId, ASYNC_STATUS(retMsg));
                sampleBankId1 = gAudioCtx.soundFontList[fontId].sampleBankId1;
                sampleBankId2 = gAudioCtx.soundFontList[fontId].sampleBankId2;
                sampleBankReloc.sampleBankId1 = sampleBankId1;
                sampleBankReloc.sampleBankId2 = sampleBankId2;
                sampleBankReloc.baseAddr1 =
                    sampleBankId1 != 0xFF ? AudioLoad_GetSampleBank(sampleBankId1, &sampleBankReloc.medium1) : 0;
                sampleBankReloc.baseAddr2 =
                    sampleBankId2 != 0xFF ? AudioLoad_GetSampleBank(sampleBankId2, &sampleBankReloc.medium2) : 0;
                AudioLoad_RelocateFontAndPreloadSamples(fontId, asyncLoad->ramAddr, &sampleBankReloc, 1);
                break;
        }
        asyncLoad->status = 0;
        gl_250C8_osSendMesg(asyncLoad->retQueue, asyncLoad->retMsg, 0);
        return;
    }

    if (asyncLoad->bytesRemaining < asyncLoad->chunkSize) {
        if (asyncLoad->medium == 1) {
            AudioLoad_AsyncDmaUnkMedium(asyncLoad->curDevAddr, asyncLoad->curRamAddr, asyncLoad->bytesRemaining,
                                        sampleBankTable->unkMediumParam);
        } else {
            AudioLoad_AsyncDma(asyncLoad, asyncLoad->bytesRemaining);
        }
        asyncLoad->bytesRemaining = 0;
        return;
    }

    if (asyncLoad->medium == 1) {
        AudioLoad_AsyncDmaUnkMedium(asyncLoad->curDevAddr, asyncLoad->curRamAddr, asyncLoad->chunkSize,
                                    sampleBankTable->unkMediumParam);
    } else {
        AudioLoad_AsyncDma(asyncLoad, asyncLoad->chunkSize);
    }

    asyncLoad->bytesRemaining -= asyncLoad->chunkSize;
    asyncLoad->curDevAddr += asyncLoad->chunkSize;
    asyncLoad->curRamAddr += asyncLoad->chunkSize;
}

#undef gAudioCtx
#undef AudioLoad_GetSampleBank
#undef AudioLoad_RelocateFontAndPreloadSamples
#undef AudioLoad_AsyncDmaUnkMedium
#undef AudioLoad_AsyncDma
#undef ASYNC_TBLTYPE
#undef ASYNC_ID
#undef ASYNC_STATUS
